package com.ruoyi.system.service.impl;
import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.ai.tool.ProfileTool; import com.ruoyi.system.domain.*; import com.ruoyi.system.mapper.*; import com.ruoyi.system.service.IEduActionPlanService; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class EduActionPlanServiceImpl implements IEduActionPlanService {
 @Autowired private EduActionPlanMapper mapper; @Autowired private LearnerProfileMapper profileMapper; @Autowired private ProfileTool profileTool;
 @Override @Transactional public Map<String,Object> generate(Long userId){ LearnerProfile profile=profileMapper.selectProfileByUserId(userId); Map<String,Object> generated=profileTool.buildActionPlan(userId,profile); EduActionPlan plan=new EduActionPlan(); plan.setUserId(userId); plan.setTitle(text(generated.get("title"),"学习行动计划")); plan.setSummary(text(generated.get("summary"),"请确认后开始执行。")); plan.setStatus("DRAFT"); plan.setSourceStatus(text(generated.get("status"),"UNKNOWN")); plan.setSourceProfileVersion(profile==null||profile.getVersion()==null?null:String.valueOf(profile.getVersion())); mapper.insertPlan(plan); Object raw=generated.get("steps"); if(raw instanceof List<?> steps){int order=1; for(Object row:steps){if(!(row instanceof Map<?,?> step))continue; EduActionPlanItem item=new EduActionPlanItem(); item.setPlanId(plan.getId()); item.setUserId(userId); item.setSortOrder(order++); item.setTitle(text(step.get("title"),"学习任务")); item.setDescription(text(step.get("description"),"")); item.setStatus("PENDING"); mapper.insertItem(item);}} return detail(userId,plan.getId()); }
 @Override public List<Map<String,Object>> list(Long userId){return mapper.selectPlansByUserId(userId).stream().map(p->view(userId,p)).toList();}
 @Override public Map<String,Object> current(Long userId){EduActionPlan p=mapper.selectCurrentPlanByUserId(userId);return p==null?Map.of():view(userId,p);}
 @Override public Map<String,Object> detail(Long userId,Long planId){EduActionPlan p=owned(userId,planId);return view(userId,p);}
 @Override @Transactional public Map<String,Object> confirm(Long userId,Long planId){EduActionPlan p=owned(userId,planId);if(!"DRAFT".equals(p.getStatus()))throw new ServiceException("Only DRAFT plans can be confirmed"); mapper.archivePlanCurrent(userId); if(mapper.activatePlan(planId,userId)!=1)throw new ServiceException("Plan activation failed");return detail(userId,planId);}
 @Override @Transactional public Map<String,Object> archive(Long userId,Long planId){owned(userId,planId);if(mapper.archivePlan(planId,userId)!=1)throw new ServiceException("Plan cannot be archived");return detail(userId,planId);}
 @Override @Transactional public Map<String,Object> regenerate(Long userId,Long planId){archive(userId,planId);return generate(userId);}
 @Override public Map<String,Object> updateItemStatus(Long userId,Long itemId,String status){if(!Set.of("PENDING","IN_PROGRESS","COMPLETED","SKIPPED").contains(status))throw new ServiceException("Invalid item status");EduActionPlanItem item=mapper.selectItemByIdAndUserId(itemId,userId);if(item==null)throw new ServiceException("Plan item not found");EduActionPlan plan=owned(userId,item.getPlanId());if(!"ACTIVE".equals(plan.getStatus()))throw new ServiceException("Only ACTIVE plan items can be updated");mapper.updateItemStatus(itemId,userId,status);return detail(userId,item.getPlanId());}
 private EduActionPlan owned(Long u,Long id){EduActionPlan p=mapper.selectPlanByIdAndUserId(id,u);if(p==null)throw new ServiceException("Plan not found");return p;} private Map<String,Object> view(Long u,EduActionPlan p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("title",p.getTitle());m.put("summary",p.getSummary());m.put("status",p.getStatus());m.put("sourceStatus",p.getSourceStatus());m.put("sourceProfileVersion",p.getSourceProfileVersion());m.put("createTime",p.getCreateTime());m.put("updateTime",p.getUpdateTime());m.put("items",mapper.selectItemsByPlanIdAndUserId(p.getId(),u));return m;} private String text(Object v,String d){return v==null||String.valueOf(v).isBlank()?d:String.valueOf(v);}
}
